metadata.tikra:source:
% README banner, drawn by voltik itself: `voltik docs/banner.tex -o docs/banner.svg`.
% The same version always writes the same bytes (crates/core/tests/banner.rs checks the committed file).
\begin{tikzpicture}
  \definecolor{mask}{HTML}{0B4F3A}
  \definecolor{trace}{HTML}{127A58}
  \definecolor{gold}{HTML}{E0B04A}
  \definecolor{silk}{HTML}{F4F3E8}
  \fill[mask] (0,0) rectangle (16,4);
  % traces under the mask
  \begin{scope}[trace, line width=2.2pt, line cap=round, line join=round]
    \draw (0.6,3.5) -- (2.0,3.5) -- (2.4,3.1);
    \draw (0.6,0.5) -- (7.4,0.5) -- (8.2,1.3) -- (8.2,2.4);
  \end{scope}
  \foreach \p in {(0.6,3.5),(0.6,0.5),(8.2,2.4)} {
    \fill[gold] \p circle (5pt); \fill[mask] \p circle (2pt);
  }
  % the name, routed as copper
  \begin{scope}[gold, line width=7pt, line cap=round, line join=round]
    \draw (1.0,2.9) -- (1.5,1.5) -- (2.0,2.9);
    \draw (2.4,1.9) -- (2.4,2.5) -- (2.8,2.9) -- (3.1,2.9) -- (3.5,2.5) -- (3.5,1.9) -- (3.1,1.5) -- (2.8,1.5) -- cycle;
    \draw (4.05,3.5) -- (4.05,1.5);
    \draw (4.65,3.4) -- (4.65,1.9) -- (5.05,1.5) -- (5.3,1.5);
    \draw (4.3,2.9) -- (5.25,2.9);
    \draw (5.85,2.9) -- (5.85,1.5);
    \draw (6.45,3.5) -- (6.45,1.5);
    \draw (7.3,2.9) -- (6.45,2.15) -- (7.35,1.5);
  \end{scope}
  \fill[gold] (5.85,3.45) circle (5pt);
  % silkscreen: Chua's circuit, as at the top of the site
  \begin{scope}[silk, text=silk, line width=0.8pt]
    \ctikzset{bipoles/length=1.05cm}
    \draw (9,3.3) to[short, -*] (10.4,3.3) to[R=$R$, -*] (12.6,3.3) to[short] (14.6,3.3)
      to[generic, l_=$N_R$] (14.6,0.7) to[short, -*] (12.6,0.7) to[short, -*] (10.4,0.7) to[short] (9,0.7) to[L=$L$] (9,3.3);
    \draw (10.4,3.3) to[C=$C_2$] (10.4,0.7);
    \draw (12.6,3.3) to[C=$C_1$] (12.6,0.7);
  \end{scope}
  \node[anchor=base west, text=silk, font=\large\ttfamily] at (1.0,0.85) {CircuiTikZ to SVG, no TeX};
\end{tikzpicture}
